def format_bytes(n):
    """Return a human-readable size such as '1.5 KB'."""
    steps = [("B", 1), ("KB", 1024), ("MB", 1024 ** 2), ("GB", 1024 ** 3), ("TB", 1024 ** 4)]
    for suffix, size in steps:
        if n < size or suffix == "B":
            return f"{n:.0f} {suffix}" if suffix == "B" else f"{n / size:.1f} {suffix}"
    return f"{n:.1f} TB"
